# ---------- Source maps ----------
source_records=[]; use_map=defaultdict(list); unknown=[]
source_sheets=[s for s in wb.sheetnames if re.match(r'^\d\d ',s)]
for sh in source_sheets:
    ws=wb[sh]; source_name=str(ws['A1'].value or sh)
    hdr=next(r for r in range(1,ws.max_row+1) if ws.cell(r,1).value=='Этап / задача')
    table=next(ws.tables[n] for n in ws.tables if range_boundaries(ws.tables[n].ref)[1]==hdr)
    _,minr,_,maxr=range_boundaries(table.ref)
    task_rows=[]
    for rr in range(minr+1,maxr+1):
        task=str(ws.cell(rr,1).value or '')
        main_txt=str(ws.cell(rr,2).value or '')
        mains=[]
        for line in main_txt.splitlines():
            payload=line[2:] if line.startswith('★ ') else line
            match=None
            for n in sorted(plugin_names,key=len,reverse=True):
                if payload==n or payload.startswith(n+' —'):
                    match=n; break
            if match: mains.append(match)
            elif payload: unknown.append((source_name,task,payload))
        other_txt=str(ws.cell(rr,3).value or '')
        others=[] if other_txt=='—' else [x.strip() for x in other_txt.split(', ') if x.strip()]
        for n in others:
            if n not in plugin_names: unknown.append((source_name,task,n))
        all_names=[]
        for n in mains+others:
            if n in plugin_names and n not in all_names: all_names.append(n)
        for n in all_names: use_map[n].append({'source':source_name,'task':task,'primary':n in mains})
        task_rows.append({'task':task,'main':mains,'others':others,'choose':str(ws.cell(rr,4).value or ''),'how':str(ws.cell(rr,5).value or ''),'position':str(ws.cell(rr,6).value or ''),'count':int(ws.cell(rr,7).value or 0)})
    source_records.append({'name':source_name,'sheet':sh,'tasks':task_rows,'count':sum(x['count'] for x in task_rows)})

