        plan=base[:3] if style=='minimal' else list(base)
        if style=='fast' and 'Channel strip / macro' in taskmap and 'Channel strip / macro' not in plan: plan=['Channel strip / macro']+plan[:3]
        if style=='creative' and 'Creative FX' in taskmap and 'Creative FX' not in plan: plan=['Creative FX']+plan[:4]
        steps=[]; alts=[]
        for task in plan[:6]:
            name,alt=choose_for(taskmap[task],style)
            if name and name not in [x['name'] for x in steps]: steps.append({'task':task,'name':name})
            if alt: alts.append(alt)
        signature=tuple(x['name'] for x in steps)
        if len(steps)<2 or signature in seen: continue
        seen.add(signature)
        slug=re.sub(r'[^a-z0-9]+','-',source['sheet'].casefold()).strip('-')
        quick.append({'id':f'quick-{slug}-{style}','source':source['name'],'goal':f'Быстрый пресет · {label}','chain':' → '.join(x['name'] for x in steps),'setup':setup,'alternatives':', '.join(dict.fromkeys(alts)),'control':control,'quickPreset':True,'steps':steps})
