        recommended=curated_by_task[(src['name'],task['task'])]
        remaining=[n for n in all_names if n not in recommended and n in plugin_by_name]
        buckets={'clean':[],'character':[],'fast':[],'other':[]}
        for n in remaining: buckets[recommendation_bucket(plugin_by_name[n])].append(n)
        task['recommended']=recommended[:6]
        task['clean']=buckets['clean'][:3]
